const first = $input.first();
const candidates = [first?.json?.body, first?.json?.data, first?.json?.response, typeof first?.json === 'string' ? first.json : null];
const xml = candidates.find((value) => typeof value === 'string') ?? JSON.stringify(first.json);

const decode = (value = '') => value
  .replace(/<!\[CDATA\[(.*?)\]\]>/gs, '$1')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

const extractTag = (block, tag) => {
  const match = block.match(new RegExp(`<${tag}>([\\s\\S]*?)<\\/${tag}>`, 'i'));
  return match ? decode(match[1]) : '';
};

const extractSource = (block) => {
  const match = block.match(/<source[^>]*>([\s\S]*?)<\/source>/i);
  return match ? decode(match[1]) : 'Google News';
};

const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/gi)]
  .map((match) => {
    const block = match[1];
    return {
      title: extractTag(block, 'title'),
      link: extractTag(block, 'link'),
      pubDate: extractTag(block, 'pubDate'),
      source: extractSource(block),
    };
  })
  .filter((item) => item.title && item.link)
  .slice(0, 3);

if (!items.length) {
  throw new Error('Nenhuma noticia foi localizada no feed RSS do Google News.');
}

const noticiasFormatadas = items
  .map((item, index) => `${index + 1}. ${item.title}\nFonte: ${item.source}\nData: ${item.pubDate || 'Nao informada'}\nLink: ${item.link}`)
  .join('\n\n');

const prompt = `Voce recebera ate 3 noticias recentes sobre Medicina, Inteligencia Artificial e Brasil. Elabore um boletim curto, claro, amigavel e pronto para WhatsApp, em portugues do Brasil, com foco em tendencias medicas, impacto pratico e relevancia para profissionais de saude. Use linguagem natural, sem exageros promocionais. Estruture com: titulo curto, abertura de uma frase, 3 bullets com insights e fechamento com uma observacao objetiva.\n\nNoticias selecionadas:\n\n${noticiasFormatadas}`;

return [{
  json: {
    termoBusca: 'Medicina Inteligencia Artificial Brasil',
    totalNoticias: items.length,
    noticias: items,
    noticiasFormatadas,
    prompt,
  },
}];
